INSERT INTO public.contents (kind, slug, title, summary, body, sort_order, published) VALUES

('guide', 'chatgpt-recharge', 'ChatGPT 充值与代充总指南', '从 Plus / Pro 各档位到充值方式一次讲清：卡充、iOS 充值、成品号有什么区别，下单前后各要注意什么。',
'# ChatGPT 充值与代充总指南\n\n本文汇总在本店充值 ChatGPT 的全部要点，第一次下单前建议完整读一遍。\n\n## 一、档位怎么选\n\n| 档位 | 官方价 | 适合人群 |\n| --- | --- | --- |\n| Plus | 20 美元/月 | 日常问答、写作、轻度使用 |\n| Pro 5X | 100 美元/月 | 高频使用 Codex / 深度研究 |\n| Pro 20X | 200 美元/月 | 专业开发者、重度依赖 AI 工作流 |\n| Pro 25X | 500 美元/月 | 极限用量、团队多开场景 |\n\n预算有限先买 Plus；需要长上下文与大额度推理再上 Pro。\n\n## 二、三种交付形态\n\n- **自助卡密充值**：付款后系统发卡密，按教程自行兑换，全程无需提供账号密码，最推荐。\n- **人工卡充**：提交订单后由渠道处理，约 1-30 分钟到账，需按要求提供 Token/Cookie。\n- **成品号**：直接交付一个已含订阅的新账号，适合没有 GPT 账号或不想折腾环境的用户。\n\n## 三、下单前必读\n\n1. 需已有 GPT 账号（成品号除外），账号需为个人版。\n2. 不建议使用微软邮箱注册的小号，容易风控；建议使用 Gmail。\n3. 谷歌账单逾期、处于宽限期、卡付未取消、自动续费未关闭、团队版、0 元购账号——以上情况请勿充值，否则可能不到账。\n4. 卡密请当天购买、当天使用；囤货多天后再反馈失效不支持退款。\n\n## 四、下单之后\n\n付款确认后自动发货，凭「订单号 + 联系方式 + 查询密码」在订单查询页查收卡密与兑换地址。详细步骤见《自动发货查收说明》。',
1, true),

('guide', 'chatgpt-plus-recharge', 'ChatGPT Plus 充值与购买', 'Plus 月卡的两种主流充值渠道（iOS 秒冲 / 菲区卡充）对比，以及覆盖、掉订阅、Codex 激活等高频问题。',
'# ChatGPT Plus 充值与购买\n\n## 一、本店 Plus 在售渠道\n\n- **iOS 充值（¥132）**：秒冲，质保 30 天，卡密可囤三天，支持覆盖现有 Plus/免费账号。\n- **菲区卡充（¥115）**：价格更低，要求账号当前无订阅（免费版）才能兑换，不支持覆盖。\n- **成品号（¥150）**：不含自有账号的独立交付，人工制作约 10 分钟至 2 小时。\n\n## 二、覆盖规则\n\niOS 渠道支持把已有 Plus 覆盖续期：覆盖成功后订阅时间从当天重新计算 1 个月。原 Plus 未到期部分不叠加时长。若当前是 Pro，Plus 卡密无法覆盖，请换新号或等 Pro 到期。\n\n## 三、常见问题速查\n\n- 兑换失败：继续重试，或等 30 分钟后再试。\n- 充值成功但未显示 Plus：退出账号重新登录 GPT。\n- 网页版看不到模型：用浏览器无痕模式重新登录。\n- Codex 额度未刷新：属官方延迟，30 分钟后重新登录 Codex 随意提问一次即可激活。\n\n## 四、质保边界\n\n质保 30 天只保「订阅不掉」，掉订阅按剩余天数退差价；封号不在质保范围内。请使用干净稳定的 IP 环境，不要多人共享或频繁切换地区登录。',
2, true),

('guide', 'chatgpt-pro-recharge', 'ChatGPT Pro 充值与购买', 'Pro 5X / 20X / 25X 三个档位的渠道差异、覆盖补差逻辑与禁止提交情形，一次说清。',
'# ChatGPT Pro 充值与购买\n\n## 一、档位与渠道\n\n| 商品 | 官方价 | 渠道特点 |\n| --- | --- | --- |\n| Pro 5X iOS | ¥650 | 秒冲，支持覆盖 |\n| Pro 5X 官方卡充 | ¥670 | 人工处理，卡密可囤五天 |\n| Pro 200刀卡充 | ¥1050 | 自动处理，质保订阅 |\n| Pro 20X 菲区续费 | ¥1090 | 仅限已是 20X 的账号续费 |\n| Pro 200刀成品号 | ¥1200 | 独立新号交付 |\n| Pro 200刀 iOS | ¥1400 | 秒冲，须 24 小时内兑换 |\n| Pro 25X 智利区 | ¥3200 | 顶配 500 刀套餐 |\n\n## 二、覆盖补差逻辑\n\nPro 支持向下覆盖：当前 Plus 购买 Pro 20X，等于补充 19X 额度；购买 Pro 5X 补充 4X 额度。同类型套餐覆盖只更新有效期，不恢复已用完的额度。\n\n## 三、以下情况请勿提交订单\n\n- 账号已是 Plus / Team / Pro 资格却拍「无订阅专用」渠道；\n- 用过非正常 Pro/Plus、0 元购、谷歌内购、低价黑冲、异常订阅记录的账号；\n- 加入过 Team 空间未切回个人版。\n\n违规提交可能导致订阅掉线、触发欺诈风控、充值失败，损失自行承担。\n\n## 四、退款规则\n\n正价订阅消费原则上不退款。若官方最终完成退款，本店在收到退款后扣除 20% 处理费用退还剩余款项。KYC、封号、需绑手机号等问题需客户自行处理，不予退款。',
3, true),

('guide', 'chatgpt-pro-5x-20x-buying-guide', 'ChatGPT Pro 5X / 20X 怎么选', '同样叫 Pro，5X 和 20X 额度差 4 倍、价差近一倍。按使用强度对号入座，不花冤枉钱。',
'# ChatGPT Pro 5X / 20X 怎么选\n\n## 一、核心区别\n\n两者都是 Pro 订阅，差别在额度：5X 对应官方 100 美元档，20X 对应 200 美元档，推理与 Codex 周额度约为 5 倍关系。\n\n## 二、按人群选择\n\n- **每天 1-3 小时中度使用**：Plus 足够，不必上 Pro。\n- **每天重度使用 + 偶尔跑 Codex**：Pro 5X 性价比最高。\n- **开发工作流依赖 Codex / 深度研究连轴转**：直接 Pro 20X，避免中途被限流打断。\n- **多设备多人共享或极限批量任务**：考虑 Pro 25X 智利区。\n\n## 三、升级路径建议\n\n首次购买建议先 5X 试用一个月，确认用量确实触顶再换 20X。注意：同类型套餐覆盖不会恢复已用完的额度，升级当月的剩余额度不结转，所以「先用满再升级」比「月中直接升」更划算。\n\n## 四、续费提醒\n\n已是菲区卡充 20X 的用户，到期前 1-2 天拍「Pro 20X 菲区续费卡密」即可原价续订，比重新开号省事且不影响额度记录。',
4, true),

('guide', 'claude-max-5x-20x-guide', 'Claude Max 5x / 20x 怎么选', 'Claude 充值 100% 触发 KYC 是真的吗？注册满月限制是什么？本文把 Claude Max 两档的规则讲透。',
'# Claude Max 5x / 20x 怎么选\n\n## 一、两档差异\n\n- **Max 5X（¥880）**：官方 100 美元档，周额度约为 Pro 的 5 倍，适合重度编码与长文档分析。\n- **Max 20X（¥1850）**：官方 200 美元档，额度再翻 4 倍，适合全天候代理式工作流。\n\n日常写作用 Pro 或干脆不买 Claude；一旦需要连续跑长任务，5X 起步才有意义。\n\n## 二、充值前必须知道的三条硬规则\n\n1. **账号必须注册满月**才能充值，否则可能不到账，后果自负。\n2. **不支持覆盖**：必须等当前会员到期后才能续费充值，重复叠加无效。\n3. **充值 MAX 档位 100% 触发 KYC 认证**，这是官方风控，验证通过后正常到账；KYC 需自行解决。\n\n## 三、两种充值方式\n\n- **SK 充值（推荐）**：充值时自动查询账户状态，确认无异常再扣款。\n- **UID 自助充值**：提供 Claude UID 即可完成，全程不需要账号密码。\n\n无论哪种方式，充值成功后出现封号均不在质保范围内。\n\n## 四、风险提示\n\n不懂 Claude 风控规则或纯新手请不要拍，容易封号。常见封号原因：频繁切换 IP、账号环境异常、多人共享。因账号自身问题导致的封号、逾期账单导致不到账，均没有退款。拍下默认接受全部条款。',
5, true),

('guide', 'grok-super-monthly-recharge', 'Grok Super 月卡值得买吗', '180 元的 Grok Super 能带来什么？和 Heavy 300 刀档差距在哪？看完再决定。',
'# Grok Super 月卡值得买吗\n\n## 一、Super 档位给什么\n\nSuperGrok 相对免费版的核心提升：更高的思考额度与更大上下文、优先访问新模型、Imagine 图像与视频生成额度、深度研究次数提升。如果你每天会用 Grok 超过半小时，Super 的体验差距是明显的。\n\n## 二、本店渠道说明\n\n- **Grok Super（¥180）**：印度区 iOS 正规 CDK，非零元购；CDK 未使用前长期有效，无固定到期时间。\n- **SuperGrok Heavy（¥2200）**：300 美元顶配档，支持直充或成品号，下单后联系客服现场制作。\n\n## 三、注意事项\n\n1. **不支持覆盖**：请确认账号当前没有任何订阅再充值。\n2. 只要持有卡密，24 小时均可自助充值；兑换入口随订单发货内容提供。\n3. 建议一个手机号只绑定 1 个 Grok 账号，避免掉订阅。\n\n## 四、售后边界\n\n全程订阅质保：质保期内掉订阅按剩余天数退差价。封号多与账号本身状态或使用环境有关（批量注册、共享、频繁换 IP、敏感话题），封号不在售后范围内。',
6, true),

('guide', 'ai-membership-before-buying', 'AI 会员购买前要注意什么', '跨品牌通用的避坑清单：邮箱、支付环境、账号状态、囤卡时效，四条红线先看再下单。',
'# AI 会员购买前要注意什么\n\n## 一、账号准备\n\n1. 除成品号外，所有充值商品都要求**已有对应平台的正常账号**。\n2. 账号必须是**个人版**；加入过 Team 空间的先切回个人版。\n3. 邮箱建议使用 Gmail / 163 / 126 / QQ；**不要用微软邮箱**，风控概率显著更高。\n\n## 二、账单状态自查\n\n充值前确认：谷歌账单无逾期、不在宽限期、旧卡付已取消、自动续费已关闭、不是 0 元购得来的账号。任何一条不满足都可能导致不到账，且此类损失不可退。\n\n## 三、卡密时效\n\n- 「秒冲」「当天使用」类卡密：**当天买当天用**，囤货失效不退。\n- 「可囤三天 / 五天」类卡密：也仅指有效期内可延后兑换，不代表无限期。\n- 兑换方式可能因官方风控随时调整，即买即用永远是最优策略。\n\n## 四、环境与售后\n\n使用干净稳定的 IP，不多人共享、不频繁切换地区。遇到问题先查单核对状态，再联系客服并附订单号、付款截图与异常截图；未查单直接来问的一般只能让你先查单。',
7, true),

('guide', 'ai-membership-auto-delivery-guide', '自动发货查收说明', '付款后卡密去哪了？三步教你在订单查询页拿到兑换凭证，以及为什么务必保存好查询密码。',
'# 自动发货查收说明\n\n## 一、发货流程\n\n1. 下单时设置「查询密码」并填写邮箱或手机号；\n2. 完成付款后系统自动核账，卡密类商品即时发放；\n3. 订单状态变为「已完成」，交付内容出现在订单查询页。\n\n## 二、怎么查收\n\n打开顶部「订单查询」，输入 **订单号 + 联系方式 + 查询密码** 三件套，即可看到交付内容面板：一键复制全部卡密、下载 TXT/CSV 备份、复制兑换网址。\n\n登录会员下单的用户，也可以直接在「个人中心 → 我的订单」查看。\n\n## 三、重要提醒\n\n- **查询密码只显示这一次**，忘记无法找回，只能凭原联系方式联系客服协助；\n- 卡密与兑换地址请妥善保管，避免泄露——谁持有卡密谁就能兑换；\n- 建议查收后立即点「下载 TXT」留存一份，防止清理浏览器数据后找不到入口。\n\n## 四、没收到怎么办\n\n支付宝扫码订单在支付处理中会自动轮询到账并发卡，稍等片刻刷新即可；长时间停留在「核账中」属于人工转账待核账，请把付款截图发给客服加急处理。',
8, true),

('guide', 'recharge-not-received', '充值不到账怎么办', '兑换了但没看到会员？先别慌，按这份排查顺序走，九成问题能自己解决。',
'# 充值不到账怎么办\n\n## 一、先确认这三件事\n\n1. 卡密是否真的兑换成功（兑换页面有无报错提示）；\n2. 充值的账号与你正在查看订阅的账号是否为**同一个**（最常见乌龙）；\n3. 距离兑换成功是否已超过 30 分钟（官方存在同步延迟）。\n\n## 二、标准排查动作\n\n- 退出账号后重新登录 GPT / Claude / Grok；\n- 网页版改用**浏览器无痕模式**登录后查看订阅状态；\n- Codex 额度未刷新：重新登录 Codex 后随意提问一次即可激活；\n- 手机端与网页端显示不一致时，以 account.openai.com 的订阅页为准。\n\n## 三、仍然没有？\n\n带上以下信息联系客服：订单号、使用的账号邮箱、兑换时间、兑换页面截图。客服会向渠道方核实卡密状态；确认卡密有效但未入账的，按商品质保条款处理（退差价或补发）。\n\n## 四、这些情况不属于不到账\n\n账号本身被封、KYC 未通过、账单逾期导致兑换被吞、使用了不符合要求的账号——这些在商品页风险说明里均已声明，不在售后范围内，下单前请务必读完条款。',
9, true),

('tutorial', 'how-to-redeem-card-secret', '卡密兑换全流程教程', '从查单拿到卡密到订阅生效的完整图文步骤，新手照着做三分钟搞定。',
'# 卡密兑换全流程教程\n\n## 第一步：查询订单\n\n在首页或顶栏进入「订单查询」，输入订单号、下单时的邮箱/手机号、查询密码，点击查询。\n\n## 第二步：拿到交付内容\n\n订单完成后页面会出现「交付内容」面板：\n\n- 点「复制全部卡密」或逐条复制；\n- 有兑换网址的商品，点「复制网址」直达兑换站；\n- 建议顺手「下载 TXT」备份一份。\n\n## 第三步：执行兑换\n\n1. 打开兑换网址（或直接前往官方订阅页）；\n2. 登录**要充值的那个账号**；\n3. 粘贴卡密并提交，等待 1-3 分钟；\n4. 回到 chatgpt.com / claude.ai，退出重登，确认订阅已生效。\n\n## 第四步：验收\n\n- ChatGPT：左下角应显示 Plus/Pro 徽标，模型列表出现高额度模型；\n- Claude：Settings → Billing 显示 Max 计划；\n- Grok：设置页显示 SuperGrok 订阅中。\n\n## 常见问题\n\n兑换按钮灰掉：多为已兑换过，检查是否重复提交。提示卡密无效：核对是否复制完整（含前缀），仍失败请在**当天**联系客服，过期反馈不受理。',
10, true),

('tutorial', 'order-and-payment-guide', '下单与支付指引', '游客也能下单：选品、填资料、设查询密码、支付宝/USDT 付款，一条链路走完。',
'# 下单与支付指引\n\n## 一、选择商品\n\n按专区（ChatGPT / Claude / Grok）找到目标档位，重点看详情页四段说明：商品详情、使用提醒、风险说明、常见问题。**与自己账号状态冲突的（如已有订阅还要拍不支持覆盖的渠道），不要下单。**\n\n## 二、提交订单\n\n1. 点击「立即购买」，选择数量；\n2. 填写联系邮箱或手机号（用于查单与售后）；\n3. 设置**查询密码**——之后取货全靠它，务必牢记；\n4. 如有优惠码在此步核销。\n\n## 三、付款方式\n\n- **支付宝**：扫码转账后等待核账，卡密类商品核账通过后自动发放；\n- **USDT**：按订单页地址与金额转账，备注订单号；\n- 登录会员下单可在「我的订单」实时跟踪状态。\n\n## 四、支付之后\n\n订单进入「核账中 → 已完成」流转。查收卡密见《卡密兑换全流程教程》。付款后请保留付款截图至少 7 天，核账异常时它是唯一凭证。',
11, true),

('policy', 'disclaimer', '第三方平台免责声明', '本站与 OpenAI、Anthropic、谷歌、xAI 等品牌的关系声明。',
